class Solution:
    def longestIdealString(self, s: str, k: int) -> int:
        dp = [0] * 26
        for ch in s:
            c = ord(ch) - ord('a')
            lo = max(0, c - k)
            hi = min(25, c + k)
            best = max(dp[lo:hi + 1])
            dp[c] = best + 1
        return max(dp)

